function formatSessionDay(date) {
  return new Intl.DateTimeFormat("en-GB", {
    weekday: "short",
    day: "numeric",
    month: "short",
    year: "numeric",
  }).format(date);
}

function generateSessionDays(startDate, endDate, weekdays) {
  if (!startDate || !endDate) return [];
  const start = new Date(`${startDate}T12:00:00`);
  const end = new Date(`${endDate}T12:00:00`);
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || start > end) return [];
  const allowed = new Set(weekdays.length ? weekdays : ["1", "2", "3", "4", "5"]);
  const days = [];
  for (const cursor = new Date(start); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
    if (cursor >= today && allowed.has(String(cursor.getDay()))) {
      days.push(formatSessionDay(cursor));
    }
  }
  return days;
}

function autumnTermLaunchDays() {
  return generateSessionDays("2026-09-02", "2026-12-18", ["1", "2", "3", "4", "5"]);
}

function sessionBlockKey(block, index = 0) {
  return block.id || `${block.label || "session"}-${block.start || ""}-${block.end || ""}-${index}`;
}

function normaliseSessionBlocks(session) {
  const blocks = Array.isArray(session?.sessionBlocks) && session.sessionBlocks.length
    ? session.sessionBlocks
    : [{
        label: session?.title || "Session",
        start: String(session?.time || "").split("-")[0]?.trim() || "",
        end: String(session?.time || "").split("-")[1]?.trim() || "",
        price: Number(session?.price || 0),
      }];
  return blocks.map((block, index) => ({
    ...block,
    key: sessionBlockKey(block, index),
    label: block.label || `${block.start || "Start"}-${block.end || "End"}`,
    price: Number(block.price || 0),
  }));
}

function parentActivityLabel(session) {
  const title = String(session?.title || session?.activity || "");
  const type = String(session?.type || "");
  if (/holiday camp|camp/i.test(`${type} ${title}`)) return "Camp";
  if (/breakfast/i.test(title)) return "Breakfast";
  if (/after[-\s]?school/i.test(title)) return "After school";
  return title || "Care";
}

function parentActivityRank(session) {
  const label = parentActivityLabel(session);
  if (label === "After school") return 1;
  if (label === "Breakfast") return 2;
  if (label === "Camp") return 3;
  return 4;
}

function isUuid(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || ""));
}

function sessionBlockIdForBooking(block) {
  return block.sessionBlockId || block.session_block_id || block.id || "";
}

function preferredParentSession(sessionList) {
  return [...sessionList].sort((a, b) => parentActivityRank(a) - parentActivityRank(b) || String(a.time || "").localeCompare(String(b.time || "")))[0];
}

function bookingBlockRows(draft) {
  if (Array.isArray(draft?.dayBreakdown) && draft.dayBreakdown.length) {
    return draft.dayBreakdown.map((row) => {
      const blocks = Array.isArray(row.blocks) && row.blocks.length
        ? row.blocks
        : [{ label: row.time || "Session", start: "", end: "", price: row.price }];
      return {
        day: row.day,
        time: row.time || blocks.map((block) => `${block.start || ""}-${block.end || ""}`.replace(/^-|-$/g, "")).filter(Boolean).join(", "),
        price: Number(row.price || blocks.reduce((sum, block) => sum + Number(block.price || 0), 0)),
        blocks: blocks.map((block) => ({
          label: block.label || `${block.start || ""}-${block.end || ""}`.replace(/^-|-$/g, "") || "Session",
          start: block.start || "",
          end: block.end || "",
          price: Number(block.price || 0),
        })),
      };
    });
  }
  return (draft?.days || []).map((day) => ({
    day,
    time: draft?.time || "",
    price: Number(draft?.total || 0) / Math.max(1, (draft?.days || []).length),
    blocks: [{ label: draft?.time || "Session", start: "", end: "", price: 0 }],
  }));
}

function bookingBlockCount(draft) {
  return bookingBlockRows(draft).reduce((sum, row) => sum + row.blocks.length, 0);
}

function bookingBlockSummary(draft, limit = 2) {
  const rows = bookingBlockRows(draft);
  if (!rows.length) return "No sessions selected";
  const visible = rows.slice(0, limit).map((row) => {
    const times = row.blocks.map((block) => `${block.start}-${block.end}`.replace(/^-|-$/g, "") || block.label).join(", ");
    return `${row.day}${times ? `: ${times}` : ""}`;
  });
  return rows.length > limit ? `${visible.join(" · ")} + ${rows.length - limit} more day${rows.length - limit === 1 ? "" : "s"}` : visible.join(" · ");
}

function bookingBlockReceiptLines(draft) {
  return bookingBlockRows(draft).flatMap((row) => [
    `${row.day}${row.time ? ` (${row.time})` : ""}`,
    ...row.blocks.map((block) => `  - ${block.label}${block.start || block.end ? ` ${block.start}-${block.end}` : ""}${block.price ? ` ${money(block.price)}` : ""}`),
  ]);
}

function bookingRowStart(row) {
  const day = parseLabDay(row.day);
  if (!day) return null;
  const timeText = row.time || row.blocks?.[0]?.start || "";
  const match = String(timeText).match(/(\d{1,2}):(\d{2})/);
  if (match) day.setHours(Number(match[1]), Number(match[2]), 0, 0);
  return day;
}

function activeBookingItemStatus(status) {
  return ["reserved", "confirmed", "waitlist", "attended"].includes(String(status || "").toLowerCase());
}

function bookingItemDate(item) {
  const metadata = item?.metadata || {};
  return metadata.sessionDate || String(item?.startsAt || item?.starts_at || "").slice(0, 10);
}

function bookingItemLabel(item) {
  const metadata = item?.metadata || {};
  return metadata.labBlockLabel || item?.sessionLabel || item?.session_label || "";
}

function bookingItemChildName(item) {
  return item?.childName || item?.child_name || "";
}

function bookingPolicyState(draft, hours = 24) {
  const starts = bookingBlockRows(draft)
    .map(bookingRowStart)
    .filter(Boolean)
    .sort((a, b) => a.getTime() - b.getTime());
  const firstStart = starts[0] || null;
  const windowHours = Math.max(0, Number(hours || 0));
  if (!firstStart) {
    return {
      allowed: false,
      label: "Date check needed",
      detail: "This booking has no valid session start date.",
      firstStart: null,
      deadline: null,
    };
  }
  const deadline = new Date(firstStart.getTime() - windowHours * 60 * 60 * 1000);
  const now = new Date();
  const allowed = now <= deadline;
  const sessionLabel = `${firstStart.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" })} ${firstStart.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" })}`;
  const deadlineLabel = deadline.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }) + " " + deadline.toLocaleTimeString("en-GB", { hour: "2-digit", minute: "2-digit" });
  return {
    allowed,
    label: allowed ? `${windowHours}h window open` : "Outside policy window",
    detail: allowed ? `Changes close ${deadlineLabel}. First session starts ${sessionLabel}.` : `Changes closed ${deadlineLabel}. First session starts ${sessionLabel}.`,
    firstStart,
    deadline,
  };
}

function parseLabDay(value) {
  if (!value) return null;
  const cleaned = String(value).replace(/,/g, "").trim();
  const currentYear = new Date().getFullYear();
  const withYear = /\b\d{4}\b/.test(cleaned) ? cleaned : `${cleaned} ${currentYear}`;
  const parsed = new Date(`${withYear} 12:00:00`);
  return Number.isNaN(parsed.getTime()) ? null : parsed;
}

function labDayIso(value) {
  const parsed = parseLabDay(value);
  return parsed ? parsed.toISOString().slice(0, 10) : "";
}

function safeDomId(value) {
  return String(value || "").toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "item";
}

function generateParentTemporaryPassword() {
  const suffix = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `Apres-${suffix}-26!`;
}

function buildMonthlyPaymentSchedule(total, count, anchorDay, depositPercent = 0) {
  const amount = Math.max(0, Number(total || 0));
  if (!amount || count < 2) return [];
  const anchor = parseLabDay(anchorDay) || new Date();
  anchor.setHours(12, 0, 0, 0);
  const totalPennies = Math.round(amount * 100);
  const depositPennies = Math.min(totalPennies, Math.max(0, Math.round(totalPennies * (Number(depositPercent || 0) / 100))));
  const remainingPennies = Math.max(0, totalPennies - depositPennies);
  const splitCount = depositPennies > 0 ? count - 1 : count;
  const basePennies = splitCount ? Math.floor(remainingPennies / splitCount) : 0;
  const remainder = remainingPennies - (basePennies * splitCount);
  return Array.from({ length: count }, (_, index) => {
    const dueDate = new Date(anchor);
    dueDate.setMonth(anchor.getMonth() + index);
    dueDate.setDate(Math.min(anchor.getDate(), 28));
    const pennies = depositPennies > 0 && index === 0
      ? depositPennies
      : basePennies + (index === count - 1 ? remainder : 0);
    return {
      number: index + 1,
      dueDate: isoDate(dueDate),
      label: dueDate.toLocaleDateString("en-GB", { day: "2-digit", month: "short", year: "numeric" }),
      amount: pennies / 100,
      status: index === 0 ? (depositPennies > 0 ? "Deposit due at booking" : "Due at booking") : "Scheduled",
      routeStatus: "Awaiting PonchoPay mandate",
    };
  });
}

function isoDate(date) {
  return date.toISOString().slice(0, 10);
}

function rangeFromPreset(mode, customStart, customEnd) {
  const today = new Date();
  today.setHours(12, 0, 0, 0);
  if (mode === "Week") {
    const start = new Date(today);
    const day = start.getDay() || 7;
    start.setDate(start.getDate() - day + 1);
    const end = new Date(start);
    end.setDate(start.getDate() + 6);
    return [isoDate(start), isoDate(end)];
  }
  if (mode === "Month") {
    return [isoDate(new Date(today.getFullYear(), today.getMonth(), 1, 12)), isoDate(new Date(today.getFullYear(), today.getMonth() + 1, 0, 12))];
  }
  if (mode === "Half-term") {
    return ["2026-06-01", "2026-07-24"];
  }
  if (mode === "Year") {
    return ["2026-06-01", "2027-05-31"];
  }
  return [customStart, customEnd];
}

