  function updateCreditEvent(bookingId, eventId, nextStatus, extras = {}) {
    const nextDrafts = drafts.map((draft) => {
      if (draft.id !== bookingId) return draft;
      return {
        ...draft,
        creditEvents: (draft.creditEvents || []).map((event, index) => {
          const currentId = event.id || `credit-${draft.id}-${index}`;
          return currentId === eventId ? {
            ...event,
            id: currentId,
            status: nextStatus,
            resolvedAt: ["Refunded", "Applied"].includes(nextStatus) ? new Date().toISOString() : event.resolvedAt,
            ...extras,
          } : event;
        }),
        updatedAt: new Date().toISOString(),
      };
    });
    persistDrafts(nextDrafts);
  }

  function markCreditRefunded(event) {
    updateCreditEvent(event.bookingId, event.eventId, "Refunded", { resolution: "Refunded to original payment route" });
    setStatus(`Credit marked refunded: ${money(event.amount)}.`);
  }

  function keepCreditOnAccount(event) {
    updateCreditEvent(event.bookingId, event.eventId, "Account credit", { resolution: "Held on parent account" });
    setStatus(`Credit kept on account: ${money(event.amount)}.`);
  }

  function applyCreditToOutstanding(event) {
    const target = drafts.find((draft) => (
      draft.id !== event.bookingId
      && draft.parentEmail === event.parentEmail
      && !["Prototype paid", "Cancelled"].includes(draft.status)
      && Number(draft.total || 0) > 0
    ));
    if (!target) {
      setStatus("No outstanding booking found for this parent credit.");
      return;
    }
    const appliedAmount = Math.min(event.amount, Number(target.total || 0));
    const nextDrafts = drafts.map((draft) => {
      if (draft.id === target.id) {
        const nextTotal = Math.max(0, Number(draft.total || 0) - appliedAmount);
        return {
          ...draft,
          total: nextTotal,
          status: nextTotal === 0 ? "Prototype paid" : draft.status,
          creditApplications: [
            ...(draft.creditApplications || []),
            { creditBookingId: event.bookingId, creditEventId: event.eventId, amount: appliedAmount, appliedAt: new Date().toISOString() },
          ],
          updatedAt: new Date().toISOString(),
        };
      }
      if (draft.id === event.bookingId) {
        return {
          ...draft,
          creditEvents: (draft.creditEvents || []).map((creditEvent, index) => {
            const currentId = creditEvent.id || `credit-${draft.id}-${index}`;
            return currentId === event.eventId ? {
              ...creditEvent,
              id: currentId,
              status: "Applied",
              appliedTo: target.id,
              appliedAmount,
              resolvedAt: new Date().toISOString(),
            } : creditEvent;
          }),
          updatedAt: new Date().toISOString(),
        };
      }
      return draft;
    });
    persistDrafts(nextDrafts);
    setStatus(`Applied ${money(appliedAmount)} credit to ${target.activity}.`);
  }

  function reconcileReferencePayments() {
    const ids = new Set(pendingWithReference.map((row) => row.id));
    if (!ids.size) {
      setStatus("No voucher, TFC or invoice payments have references ready to reconcile.");
      return;
    }
    const nextDrafts = drafts.map((draft) => ids.has(draft.id)
      ? { ...draft, status: "Prototype paid", reconciledAt: new Date().toISOString(), updatedAt: new Date().toISOString() }
      : draft);
    persistDrafts(nextDrafts);
    setStatus(`${ids.size} referenced payment${ids.size === 1 ? "" : "s"} reconciled locally.`);
  }

  function updateDraftStatus(id, nextStatus) {
    const draft = drafts.find((item) => item.id === id);
    const nextDrafts = drafts.map((draft) => draft.id === id ? { ...draft, status: nextStatus, updatedAt: new Date().toISOString() } : draft);
    persistDrafts(nextDrafts);
    if (draft) {
      recordGovernanceEvent("Booking status changed", `${draft.parentName || "Parent"} · ${draft.activity}: ${draft.status} to ${nextStatus}.`, {
        category: "Bookings",
        risk: ["Prototype paid", "Cancelled", "Payment failed"].includes(nextStatus) ? "High" : "Medium",
        approvalRequired: ["Prototype paid", "Cancelled", "Payment failed"].includes(nextStatus),
        reason: approvalReason,
      });
    }
  }

  function updateBookingReviewState(id, reviewState) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const nextDrafts = drafts.map((item) => item.id === id ? {
      ...item,
      reviewState,
      reviewedBy: activeRole,
      reviewedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    } : item);
    persistDrafts(nextDrafts);
    recordGovernanceEvent("Booking review updated", `${draft.parentName || "Parent"} · ${draft.activity}: ${reviewState}.`, {
      category: "Bookings",
      risk: reviewState === "Approved" ? "Medium" : "High",
      approvalRequired: reviewState === "Approved",
      reason: approvalReason,
    });
    setStatus(`Booking review marked ${reviewState.toLowerCase()}.`);
  }

  function openBookingReviewAction(id, type) {
    setActiveReviewId(id);
    setBookingReviewAction({ id, type });
  }

  function confirmBookingReviewAction() {
    if (!bookingReviewAction) return;
    const { id, type } = bookingReviewAction;
    if (type === "approve") {
      if (bookingReviewActionBlocked) {
        setStatus("Approval blocked until missing details or payment issues are resolved.");
        return;
      }
      updateBookingReviewState(id, "Approved");
      setBookingReviewAction(null);
      return;
    }
    if (type === "hold") {
      updateBookingReviewState(id, "On hold");
      setBookingReviewAction(null);
      return;
    }
    if (type === "request") {
      requestBookingInfo(id);
      setBookingReviewAction(null);
      return;
    }
    if (type === "amend") {
      if (!bookingReviewActionAmendPolicy?.allowed) {
        setStatus(`Amendment blocked: ${bookingReviewActionAmendPolicy?.detail || "Policy window closed."}`);
        return;
      }
      setBookingReviewAction(null);
      amendParentBooking(id);
      return;
    }
    if (type === "cancel") {
      if (!bookingReviewActionCancelPolicy?.allowed) {
        setStatus(`Cancellation blocked: ${bookingReviewActionCancelPolicy?.detail || "Policy window closed."}`);
        return;
      }
      setBookingReviewAction(null);
      cancelParentBooking(id);
    }
  }

  function requestBookingInfo(id) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    updateBookingReviewState(id, "Needs info");
    const message = {
      id: `review-info-${Date.now()}`,
      createdAt: new Date().toISOString(),
      template: "Admin info request",
      recipient: draft.parentEmail || "parent@example.com",
      bookingId: draft.id,
      subject: `More detail needed · ${draft.activity}`,
      body: `Hi ${draft.parentName || "there"}, please check collection, emergency and consent details for ${draft.activity} so we can approve the booking.`,
      channel: "Email",
      status: "Queued",
      priority: "High",
    };
    persistMessages([message, ...messageLog].slice(0, 80));
    setStatus("Information request queued locally for the parent.");
  }

