          ...(row.status === "Prototype paid"
            ? [{ label: "Payment confirmed and invoice marked paid", at: new Date(now + index + 2).toISOString() }]
            : row.paymentMethod === "voucher" && !row.missing
              ? [{ label: "Voucher reference captured for PonchoPay match", at: new Date(now + index + 2).toISOString() }]
              : [{ label: "Parent action still required", at: new Date(now + index + 2).toISOString() }]),
