  function startParentAmendment(id) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const policy = bookingPolicyState(draft, rules.amendmentHours);
    if (!policy.allowed) {
      setStatus(`Amendment blocked: ${policy.detail}`);
      return;
    }
    const session = sessions.find((item) => item.id === draft.sessionId);
    const sessionBlocks = normaliseSessionBlocks(session);
    const dayBreakdown = bookingBlockRows(draft).map((row) => {
      const blockKeys = row.blocks
        .map((savedBlock) => sessionBlocks.find((block) => block.start === savedBlock.start && block.end === savedBlock.end)?.key)
        .filter(Boolean);
      const hasCurrentBlockMatch = blockKeys.length > 0;
      const legacyBlocks = row.blocks.map((block, index) => ({
        label: block.label,
        start: block.start,
        end: block.end,
        price: Number(block.price || row.price || 0),
        key: `legacy-${row.day}-${index}`,
      }));
      const keys = hasCurrentBlockMatch ? blockKeys : legacyBlocks.map((block) => block.key);
      const blocks = hasCurrentBlockMatch ? sessionBlocks.filter((block) => keys.includes(block.key)) : legacyBlocks;
      return {
        day: row.day,
        time: blocks.length ? `${blocks[0].start}-${blocks[blocks.length - 1].end}` : row.time || session?.time || "",
        price: hasCurrentBlockMatch ? blocks.reduce((sum, block) => sum + Number(block.price || 0), 0) : Number(row.price || 0),
        blockKeys: keys,
        blocks: blocks.map((block) => ({
          key: block.key,
          label: block.label,
          start: block.start,
          end: block.end,
          price: block.price,
        })),
      };
    });
    setAmendment({
      id: draft.id,
      sessionId: draft.sessionId,
      activity: draft.activity,
      site: draft.site,
      days: dayBreakdown.map((row) => row.day),
      dayBreakdown,
      children: [...(draft.children || (draft.childName ? [draft.childName] : []))],
      addOns: [...(draft.addOns || [])],
      paymentMethod: draft.paymentMethod || "card",
      paymentReference: draft.paymentReference || "",
      status: draft.status || "Amendment draft",
    });
    setStatus("Amendment editor opened for the selected booking.");
  }

  function updateAmendmentField(field, value) {
    setAmendment((current) => current ? { ...current, [field]: value } : current);
  }

  function toggleAmendmentDay(day) {
    setAmendment((current) => {
      if (!current) return current;
      const days = current.days || [];
      const removing = days.includes(day);
      const session = sessions.find((item) => item.id === current.sessionId);
      const blocks = normaliseSessionBlocks(session);
      const nextDays = removing ? days.filter((item) => item !== day) : [...days, day];
      const nextBreakdown = removing
        ? (current.dayBreakdown || []).filter((row) => row.day !== day)
        : [
            ...(current.dayBreakdown || []),
            {
              day,
              time: session?.time || "",
              price: blocks.reduce((sum, block) => sum + Number(block.price || 0), 0),
              blockKeys: blocks.map((block) => block.key),
              blocks: blocks.map((block) => ({
                label: block.label,
                start: block.start,
                end: block.end,
                price: block.price,
              })),
            },
          ];
      return { ...current, days: nextDays, dayBreakdown: nextBreakdown };
    });
  }

  function toggleAmendmentBlock(day, block) {
    setAmendment((current) => {
      if (!current) return current;
      const session = sessions.find((item) => item.id === current.sessionId);
      const blocks = normaliseSessionBlocks(session);
      const sourceBlocks = blocks.some((item) => item.key === block.key) ? blocks : [block, ...blocks];
      const allKeys = sourceBlocks.map((item) => item.key);
      const existingRow = (current.dayBreakdown || []).find((row) => row.day === day);
      const existingKeys = existingRow?.blockKeys?.length ? existingRow.blockKeys.filter((key) => allKeys.includes(key)) : [];
      const nextKeys = existingKeys.includes(block.key)
        ? existingKeys.filter((key) => key !== block.key)
        : [...existingKeys, block.key];
      const otherRows = (current.dayBreakdown || []).filter((row) => row.day !== day);
      if (!nextKeys.length) {
        return {
          ...current,
          days: (current.days || []).filter((item) => item !== day),
          dayBreakdown: otherRows,
        };
      }
      const selectedBlocks = sourceBlocks.filter((item) => nextKeys.includes(item.key));
      const nextRow = {
        day,
        time: selectedBlocks.length ? `${selectedBlocks[0].start}-${selectedBlocks[selectedBlocks.length - 1].end}` : session?.time || "",
        price: selectedBlocks.reduce((sum, item) => sum + Number(item.price || 0), 0),
        blockKeys: nextKeys,
        blocks: selectedBlocks.map((item) => ({
          label: item.label,
          start: item.start,
          end: item.end,
          price: item.price,
        })),
      };
      return {
        ...current,
        days: (current.days || []).includes(day) ? current.days : [...(current.days || []), day],
        dayBreakdown: [...otherRows, nextRow].sort((a, b) => (current.days || []).indexOf(a.day) - (current.days || []).indexOf(b.day)),
      };
    });
  }

  function toggleAmendmentChild(name) {
    setAmendment((current) => {
      if (!current) return current;
      const children = current.children || [];
      return { ...current, children: children.includes(name) ? children.filter((item) => item !== name) : [...children, name] };
    });
  }

  function toggleAmendmentAddOn(label) {
    setAmendment((current) => {
      if (!current) return current;
      const addOns = current.addOns || [];
      return { ...current, addOns: addOns.includes(label) ? addOns.filter((item) => item !== label) : [...addOns, label] };
    });
  }

  async function saveParentAmendment() {
    if (!amendment || !amendmentSession) return;
    if (amendmentPolicy && !amendmentPolicy.allowed) {
      setStatus(`Amendment blocked: ${amendmentPolicy.detail}`);
      return;
    }
    if (!amendment.days.length || !amendment.children.length) {
      setStatus("Amendment needs at least one day and one child.");
      return;
    }
    let backendAmendment = null;
    let backendAddedItems = 0;
    let backendRemovedItems = 0;
    if (amendmentUsesRealApi && amendmentRemovedBackendItemIds.length) {
      try {
        backendAmendment = await removeParentBookingItems({
          bookingId: amendmentLiveBookingId,
          bookingItemIds: amendmentRemovedBackendItemIds,
          reason: `Parent portal amendment within ${rules.amendmentHours}h policy`,
        });
        backendRemovedItems = Number(backendAmendment?.removedItems || amendmentRemovedBackendItemIds.length || 0);
      } catch (error) {
        setStatus(`Amendment failed: ${error instanceof Error ? error.message : "Unable to amend booking."}`);
        return;
      }
    }
    if (amendmentUsesRealApi && amendmentAddedBackendItems.length) {
      try {
        backendAmendment = await addParentBookingItems({
          bookingId: amendmentLiveBookingId,
          items: amendmentAddedBackendItems,
          reason: `Parent portal amendment within ${rules.amendmentHours}h policy`,
        });
        backendAddedItems = Number(backendAmendment?.addedItems || amendmentAddedBackendItems.length || 0);
      } catch (error) {
        setStatus(`Amendment failed: ${error instanceof Error ? error.message : "Unable to amend booking."}`);
        return;
      }
    }
    const nextStatus = amendmentDelta > 0
      ? "Payment due"
      : amendment.paymentMethod === "card"
        ? "Prototype paid"
        : amendmentTotal > 0
          ? "Payment reference pending"
          : "Amended";
    const nextDrafts = drafts.map((draft) => draft.id === amendment.id ? {
      ...draft,
      days: amendment.days,
      dayBreakdown: amendmentDayRows.map((row) => ({
        day: row.day,
        time: row.time,
        price: row.price,
        capacity: draft.dayBreakdown?.find((item) => item.day === row.day)?.capacity || draft.capacity,
        paymentRoute: draft.dayBreakdown?.find((item) => item.day === row.day)?.paymentRoute || draft.paymentRoute,
        blocks: row.blocks.map((block) => ({
          label: block.label,
          start: block.start,
          end: block.end,
          price: block.price,
        })),
      })),
      children: amendment.children,
      childCount: amendment.children.length,
      childName: amendment.children[0] || draft.childName,
      addOns: amendment.addOns,
      paymentMethod: amendment.paymentMethod,
      paymentReference: amendment.paymentReference,
      status: nextStatus,
      total: amendmentTotal,
      outstandingBalance: backendAmendment?.booking
        ? Number(backendAmendment.booking.outstandingBalance || 0)
        : Math.max(0, Number(draft.outstandingBalance ?? amendmentTotal) + Math.max(0, amendmentDelta)),
      backendAmendment: backendAmendment || draft.backendAmendment || null,
      backendItems: backendAmendment?.items || draft.backendItems || [],
      realBookingMessage: backendAmendment?.booking
        ? `Amended through booking API. ${backendAddedItems} added, ${backendRemovedItems} removed.`
        : draft.realBookingMessage,
      amendedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      creditEvents: [
        ...(draft.creditEvents || []),
        ...(amendmentDelta < 0 ? [{
          id: `credit-${Date.now()}`,
          amount: Math.abs(amendmentDelta),
          createdAt: new Date().toISOString(),
          reason: "Amendment reduced booking value",
          type: "Amendment credit",
        }] : []),
      ],
      amendmentHistory: [
        ...(draft.amendmentHistory || []),
        {
          at: new Date().toISOString(),
          fromTotal: Number(draft.total || 0),
          toTotal: amendmentTotal,
          delta: amendmentTotal - Number(draft.total || 0),
          days: amendment.days,
          dayBreakdown: amendmentDayRows.map((row) => ({
            day: row.day,
            time: row.time,
            price: row.price,
            blocks: row.blocks.map((block) => ({
              label: block.label,
              start: block.start,
              end: block.end,
              price: block.price,
            })),
          })),
          children: amendment.children,
          addOns: amendment.addOns,
          paymentMethod: amendment.paymentMethod,
          backend: backendAmendment ? {
            addedItems: backendAddedItems,
            addedTotal: backendAmendment.addedTotal,
            removedItems: backendRemovedItems,
            releasedHolds: backendAmendment.releasedHolds,
            removedTotal: backendAmendment.removedTotal,
          } : null,
        },
      ],
    } : draft);
    persistDrafts(nextDrafts);
    const amendedDraft = nextDrafts.find((draft) => draft.id === amendment.id) || null;
    if (amendedDraft) {
      const message = {
        id: `parent-amendment-${Date.now()}`,
        createdAt: new Date().toISOString(),
        template: "Booking change",
        channel: notificationChannelForEmail(amendedDraft.parentEmail || activeFamily.email, "bookingChanges", "Email"),
        recipient: amendedDraft.parentEmail || activeFamily.email || "parent@example.com",
        bookingId: amendedDraft.id,
        subject: `Booking amended · ${amendedDraft.activity}`,
        body: `Hi ${amendedDraft.parentName || activeFamily.parentName || "there"}, your booking has been amended. New sessions: ${bookingBlockSummary(amendedDraft, 3)}. New total: ${money(Number(amendedDraft.total || 0))}. ${amendmentDelta < 0 ? `Credit raised: ${money(Math.abs(amendmentDelta))}.` : amendmentDelta > 0 ? `Additional amount due: ${money(amendmentDelta)}.` : "No price change."}`,
        status: "Sent",
      };
      persistMessages([message, ...messageLog].slice(0, 70));
    }
    setConfirmation(nextDrafts.find((draft) => draft.id === amendment.id) || null);
    setAmendment(null);
    if (backendAmendment) {
      refreshLiveParentLedger({ quiet: true });
    }
    if (amendmentDelta > 0) {
      openParentPaymentCheckout("single", amendment.id, amendment.paymentMethod || "card", {
        reason: "amendment",
        amountOverride: amendmentDelta,
        source: "parent-amendment",
      });
    }
    setStatus(amendmentDelta < 0
      ? `Booking amended${backendAmendment ? " through the booking API" : ""}. Credit created: ${money(Math.abs(amendmentDelta))}.`
      : amendmentDelta > 0
        ? `Booking amended${backendAmendment ? " through the booking API" : ""}. Extra payment ready: ${money(amendmentDelta)}.`
        : `Booking amended${backendAmendment ? " through the booking API" : ""}. No extra payment due.`);
  }

  function duplicateDraft(id) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const copy = { ...draft, id: `lab-booking-${Date.now()}`, createdAt: new Date().toISOString(), status: "Amendment draft" };
    persistDrafts([copy, ...drafts].slice(0, 20));
  }

  function amendParentBooking(id) {
    startParentAmendment(id);
  }

  function cancelParentBooking(id) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const policy = bookingPolicyState(draft, rules.cancellationHours);
    if (!policy.allowed) {
      setStatus(`Cancellation blocked: ${policy.detail}`);
      return;
    }
    setCancellationReview({ id });
    setStatus("Review the cancellation impact before confirming.");
  }

  async function cancelParentBookedSession(draftId, day) {
    const draft = drafts.find((item) => item.id === draftId);
    if (!draft) return;
    const dayRow = bookingBlockRows(draft).find((row) => row.day === day);
    const sessionRow = parentBookedSessionRows.find((row) => row.draftId === draftId && row.day === day && row.status !== "Cancelled");
    const start = dayRow ? bookingRowStart(dayRow) : null;
    if (!dayRow || !start) {
      setStatus("This session could not be checked. Please contact the office.");
      return;
    }
    if (start <= new Date()) {
      setStatus("Only future sessions can be cancelled from the parent account.");
      return;
    }
    if ((draft.cancelledSessions || []).some((item) => item.day === day)) {
      setStatus("That session has already been cancelled.");
      return;
    }
    if (parentSessionCancellingId) return;

    let backendAmendment = null;
    if (sessionRow?.usesRealApi) {
      setParentSessionCancellingId(sessionRow.id);
      setStatus("Cancelling this session in the live booking system...");
      try {
        backendAmendment = await removeParentBookingItems({
          bookingId: sessionRow.liveBookingId,
          bookingItemIds: sessionRow.liveItemIds,
          reason: `Parent cancelled ${day} from their account`,
        });
      } catch (error) {
        setParentSessionCancellingId("");
        setStatus(`Session cancellation failed: ${error instanceof Error ? error.message : "Unable to update the live booking."}`);
        return;
      }
    } else {
      setParentSessionCancellingId(sessionRow?.id || `${draftId}::${safeDomId(day)}`);
    }

    const now = new Date().toISOString();
    const childMultiplier = Math.max(1, Number(draft.childCount || draft.children?.length || 1));
    const creditAmount = Math.max(0, Number(backendAmendment?.removedTotal ?? dayRow.price ?? 0) * (backendAmendment ? 1 : childMultiplier));
    const remainingDayBreakdown = (draft.dayBreakdown || []).filter((row) => row.day !== day);
    const remainingDays = (draft.days || []).filter((item) => item !== day);
    const nextStatus = remainingDays.length ? "Partially cancelled" : "Cancelled";
    const cancellationRecord = {
      id: `session-cancel-${Date.now()}`,
      day,
      blocks: dayRow.blocks,
      amount: creditAmount,
      cancelledAt: now,
      reason: "Parent cancelled future session",
      status: "Credit issued",
    };
    const nextDrafts = drafts.map((item) => item.id === draft.id ? {
      ...item,
      days: remainingDays,
      dayBreakdown: remainingDayBreakdown,
      status: nextStatus,
      updatedAt: now,
      outstandingBalance: backendAmendment?.booking
        ? Number(backendAmendment.booking.outstandingBalance || 0)
        : Math.max(0, Number(item.outstandingBalance || 0) - creditAmount),
      total: backendAmendment?.booking
        ? Number(backendAmendment.booking.totalAmount || item.total || 0)
        : item.total,
      backendAmendment: backendAmendment || item.backendAmendment || null,
      backendItems: backendAmendment?.items || item.backendItems || [],
      realBookingMessage: backendAmendment?.booking
        ? `Session cancelled through booking API. ${backendAmendment.removedItems || 0} item${backendAmendment.removedItems === 1 ? "" : "s"} removed and ${backendAmendment.releasedHolds || 0} hold${backendAmendment.releasedHolds === 1 ? "" : "s"} released.`
        : item.realBookingMessage,
      cancelledSessions: [
        ...(item.cancelledSessions || []),
        cancellationRecord,
      ],
      creditEvents: [
        ...(item.creditEvents || []),
        {
          id: `credit-${Date.now()}`,
          amount: creditAmount,
          createdAt: now,
          reason: `Cancelled ${day}`,
          status: "Open",
          type: "Session cancellation credit",
        },
      ],
      amendmentHistory: [
        ...(item.amendmentHistory || []),
        {
          at: now,
          type: "Session cancellation",
          day,
          creditAmount,
          policy: "Parent cancelled a future session from their account.",
          backend: backendAmendment ? {
            removedItems: backendAmendment.removedItems,
            releasedHolds: backendAmendment.releasedHolds,
            removedTotal: backendAmendment.removedTotal,
          } : null,
        },
      ],
    } : item);
    persistDrafts(nextDrafts);
    const message = {
      id: `parent-session-cancellation-${Date.now()}`,
      createdAt: now,
      template: "Session cancellation confirmation",
      channel: notificationChannelForEmail(draft.parentEmail || activeFamily.email, "bookingChanges", "Email"),
      recipient: draft.parentEmail || activeFamily.email || "parent@example.com",
      bookingId: draft.id,
      subject: `Session cancelled · ${day}`,
      body: `Your ${draft.activity} session on ${day} has been cancelled. ${money(creditAmount)} has been added as account credit.`,
      status: "Sent",
    };
    persistMessages([message, ...messageLog].slice(0, 70));
    setSelectedParentBookingId(draft.id);
    setParentSessionCancellingId("");
    if (backendAmendment) {
      refreshLiveParentLedger({ quiet: true });
    }
    setStatus(`${day} cancelled${backendAmendment ? " through the booking API" : ""}. ${money(creditAmount)} credit added to the parent account.`);
  }

  async function confirmParentCancellation() {
    const draft = cancellationDraft;
    if (!draft) {
      setCancellationReview(null);
      return;
    }
    const policy = bookingPolicyState(draft, rules.cancellationHours);
    if (!policy.allowed) {
      setStatus(`Cancellation blocked: ${policy.detail}`);
      setCancellationReview(null);
      return;
    }
    if (cancellationSubmitting) return;

    setCancellationSubmitting(true);
    const creditAmount = draft.status === "Prototype paid" ? Number(draft.total || 0) : 0;
    const now = new Date().toISOString();
    let backendCancellation = null;
    if (cancellationUsesRealApi) {
      try {
        backendCancellation = await cancelRealParentBooking({
          bookingId: cancellationLiveBookingId,
          reason: `Parent portal cancellation within ${rules.cancellationHours}h policy`,
        });
      } catch (error) {
        setCancellationSubmitting(false);
        setStatus(`Cancellation failed: ${error instanceof Error ? error.message : "Unable to cancel booking."}`);
        return;
      }
    }

    const nextDrafts = drafts.map((item) => item.id === draft.id ? {
      ...item,
      status: "Cancelled",
      cancelledAt: now,
      updatedAt: now,
      outstandingBalance: 0,
      backendCancellation: backendCancellation || item.backendCancellation || null,
      realBookingMessage: backendCancellation?.booking
        ? `Cancelled through booking API. ${backendCancellation.releasedHolds || 0} capacity hold${backendCancellation.releasedHolds === 1 ? "" : "s"} released.`
        : item.realBookingMessage,
      creditEvents: [
        ...(item.creditEvents || []),
        ...(creditAmount > 0 ? [{
          id: `credit-${Date.now()}`,
          amount: creditAmount,
          createdAt: now,
          reason: `Cancelled under ${rules.cancellationHours}h policy`,
          type: "Cancellation credit",
        }] : []),
      ],
      amendmentHistory: [
        ...(item.amendmentHistory || []),
        {
          at: now,
          type: "Cancellation",
          policy: policy.detail,
          creditAmount,
          backend: backendCancellation ? {
            cancelled: backendCancellation.cancelled,
            releasedHolds: backendCancellation.releasedHolds,
            cancelledItems: backendCancellation.cancelledItems,
          } : null,
        },
      ],
    } : item);
    persistDrafts(nextDrafts);
    const message = {
      id: `parent-cancellation-${Date.now()}`,
      createdAt: now,
      template: "Cancellation confirmation",
      channel: notificationChannelForEmail(draft.parentEmail || activeFamily.email, "bookingChanges", "Email"),
      recipient: draft.parentEmail || activeFamily.email || "parent@example.com",
      bookingId: draft.id,
      subject: `Booking cancelled · ${draft.activity}`,
      body: cancellationMessagePreview,
      status: "Sent",
    };
    persistMessages([message, ...messageLog].slice(0, 70));
    setCancellationReview(null);
    setCancellationSubmitting(false);
    if (backendCancellation) {
      refreshLiveParentLedger({ quiet: true });
    }
    setStatus(creditAmount > 0
      ? `Booking cancelled${backendCancellation ? " through the booking API" : ""}. Parent credit created: ${money(creditAmount)}.`
      : `Booking cancelled${backendCancellation ? " through the booking API" : ""} under the ${rules.cancellationHours}h cancellation policy.`);
  }

  function openParentPaymentCheckout(mode, ids, method = "card", options = {}) {
    const selectedIds = Array.isArray(ids) ? ids : [ids];
    const payableIds = selectedIds.filter(Boolean);
    if (!payableIds.length) {
      setStatus("No invoices are selected for payment.");
      return;
    }
    const checkoutMethod = ["card", "tfc", "voucher"].includes(method) ? method : "card";
    setParentPaymentCheckout({
      mode,
      ids: payableIds,
      method: checkoutMethod,
      reason: options.reason || "invoice",
      amountOverride: options.amountOverride,
      source: options.source || "",
    });
  }

  function payParentBooking(id, method = "card", options = {}) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const now = new Date().toISOString();
    const autoReconcile = ["tfc", "voucher"].includes(method);
    const referencePrefix = method === "tfc" ? "TFC" : method === "voucher" ? "VOUCHER" : "PORTAL";
    const methodLabel = method === "tfc" ? "Tax-Free Childcare" : method === "voucher" ? "Childcare voucher" : "Card";
    const previousBalance = Math.max(0, Number(draft.outstandingBalance ?? draft.total ?? 0));
    const paymentAmount = Math.min(previousBalance || Number(draft.total || 0), Math.max(0, Number(options.amountOverride ?? previousBalance ?? draft.total ?? 0)));
    const nextBalance = Math.max(0, previousBalance - paymentAmount);
    const paymentReason = options.reason === "amendment" ? "amendment balance" : "invoice";
    const checkout = options.checkout || null;
    const nextDrafts = drafts.map((item) => item.id === id ? {
      ...item,
      status: autoReconcile ? "Payment reference pending" : nextBalance > 0 ? "Partially paid" : "Prototype paid",
      paymentMethod: method,
      paymentLabel: methodLabel,
      paymentStatus: autoReconcile ? "Awaiting auto reconciliation" : nextBalance > 0 ? "Part payment received" : "Paid",
      invoiceStatus: autoReconcile ? "Outstanding until PonchoPay matches the payment" : nextBalance > 0 ? "Part paid; balance remains" : "Paid receipt issued",
      outstandingBalance: autoReconcile ? previousBalance : nextBalance,
      paymentPlanStatus: item.paymentPlan === "Monthly" ? (autoReconcile ? `${methodLabel} auto reconciliation pending` : "Plan settled") : item.paymentPlanStatus,
      paymentSchedule: Array.isArray(item.paymentSchedule)
        ? item.paymentSchedule.map((installment) => ({
          ...installment,
          status: autoReconcile ? installment.status : "Paid",
          routeStatus: autoReconcile ? `Awaiting ${methodLabel} auto reconciliation` : "Reconciled by PonchoPay",
          paidAt: autoReconcile ? installment.paidAt : installment.paidAt || now,
        }))
        : item.paymentSchedule,
      paymentReference: item.paymentReference || `${referencePrefix}-${Date.now().toString().slice(-6)}`,
      reconciledAt: autoReconcile ? item.reconciledAt : now,
      ponchoCheckout: checkout || item.ponchoCheckout,
      checkoutSessionStatus: checkout?.status || item.checkoutSessionStatus,
      checkoutUrl: checkout?.checkoutUrl || item.checkoutUrl,
      paymentTimeline: [
        ...(item.paymentTimeline || []),
        { label: autoReconcile ? `${methodLabel} reference saved for PonchoPay auto reconciliation` : `${methodLabel} ${paymentReason} payment confirmed through parent checkout`, at: now, amount: paymentAmount },
      ],
      updatedAt: now,
    } : item);
    persistDrafts(nextDrafts);
    const paidDraft = nextDrafts.find((item) => item.id === id) || draft;
    const message = {
      id: `parent-receipt-${Date.now()}`,
      createdAt: now,
      template: autoReconcile ? "Payment reference" : "Payment receipt",
      channel: notificationChannelForEmail(paidDraft.parentEmail || activeFamily.email, "invoices", "Email"),
      recipient: paidDraft.parentEmail || activeFamily.email || "parent@example.com",
      bookingId: paidDraft.id,
      subject: `${autoReconcile ? "Payment reference saved" : "Invoice paid"} · ${paidDraft.activity}`,
      body: autoReconcile
        ? `Hi ${paidDraft.parentName || activeFamily.parentName || "there"}, your ${methodLabel} reference has been saved for ${paidDraft.activity}. Amount awaiting PonchoPay auto reconciliation: ${money(paymentAmount)}. Reference: ${paidDraft.paymentReference || "portal"}. We will issue the receipt when the payment is matched.`
        : `Hi ${paidDraft.parentName || activeFamily.parentName || "there"}, your ${paymentReason} for ${paidDraft.activity} has been marked paid. Amount: ${money(paymentAmount)}. Method: ${methodLabel}. Reference: ${paidDraft.paymentReference || "portal"}.`,
    };
    persistMessages([message, ...messageLog].slice(0, 70));
    setStatus(autoReconcile ? `${methodLabel} reference saved for PonchoPay auto reconciliation.` : "Prototype payment marked as received and receipt added to the parent inbox.");
  }

  function attachPonchoCheckoutToBooking(id, checkout, amount, reason = "invoice") {
    if (!checkout) return;
    const now = new Date().toISOString();
    const nextDrafts = drafts.map((item) => item.id === id ? {
      ...item,
      status: "Payment due",
      paymentStatus: "PonchoPay checkout ready",
      invoiceStatus: reason === "amendment" ? "Amended invoice awaiting PonchoPay payment" : "Invoice awaiting PonchoPay payment",
      ponchoCheckout: checkout,
      checkoutSessionStatus: checkout.status,
      checkoutUrl: checkout.checkoutUrl,
      paymentReference: item.paymentReference || checkout.providerReference || "",
      outstandingBalance: Math.max(0, Number(item.outstandingBalance ?? item.total ?? 0)),
      paymentTimeline: [
        ...(item.paymentTimeline || []),
        {
          label: checkout.checkoutUrl ? "PonchoPay checkout link created" : "PonchoPay checkout attempted",
          at: now,
          amount,
          reason,
          status: checkout.status,
        },
      ],
      updatedAt: now,
    } : item);
    persistDrafts(nextDrafts);
  }

  function payNextPlanInstallment(id, method = "card") {
    const draft = drafts.find((item) => item.id === id);
    if (!draft || draft.paymentPlan !== "Monthly" || !Array.isArray(draft.paymentSchedule)) return;
    const nextInstallment = draft.paymentSchedule.find((item) => item.status !== "Paid");
    if (!nextInstallment) {
      setStatus("All instalments are already marked paid for this plan.");
      return;
    }
    const now = new Date().toISOString();
    const autoReconcile = ["tfc", "voucher"].includes(method);
    const methodLabel = method === "tfc" ? "Tax-Free Childcare" : method === "voucher" ? "Childcare voucher" : "Card";
    const referencePrefix = method === "tfc" ? "TFC" : method === "voucher" ? "VOUCHER" : "PONCHO";
    const nextDrafts = drafts.map((item) => {
      if (item.id !== id) return item;
      const paymentSchedule = item.paymentSchedule.map((installment) => installment.number === nextInstallment.number ? {
        ...installment,
        status: autoReconcile ? "Pending" : "Paid",
        routeStatus: autoReconcile ? `Awaiting ${methodLabel} auto reconciliation` : "Reconciled by PonchoPay",
        paidAt: autoReconcile ? installment.paidAt : now,
        reference: `${referencePrefix}-${Date.now().toString().slice(-6)}`,
      } : installment);
      const planSettled = paymentSchedule.every((installment) => installment.status === "Paid");
      return {
        ...item,
        paymentMethod: method,
        paymentLabel: methodLabel,
        paymentSchedule,
        paymentStatus: autoReconcile ? "Awaiting auto reconciliation" : item.paymentStatus,
        invoiceStatus: autoReconcile ? "Outstanding until PonchoPay matches the payment" : item.invoiceStatus,
        status: planSettled ? "Prototype paid" : "Payment plan active",
        paymentPlanStatus: autoReconcile ? `${methodLabel} instalment awaiting auto reconciliation` : planSettled ? "Plan settled" : "Next instalment scheduled",
        paymentReference: item.paymentReference || `PLAN-${Date.now().toString().slice(-6)}`,
        paymentTimeline: [
          ...(item.paymentTimeline || []),
          { label: autoReconcile ? `Instalment ${nextInstallment.number} ${methodLabel} reference saved for auto reconciliation` : `Instalment ${nextInstallment.number} paid by ${methodLabel} via parent checkout`, at: now },
        ],
        updatedAt: now,
      };
    });
    persistDrafts(nextDrafts);
    setStatus(autoReconcile ? `Instalment ${nextInstallment.number} saved for ${methodLabel} auto reconciliation.` : `Instalment ${nextInstallment.number} marked paid and reconciled locally.`);
  }

  function updatePlanPaymentMethod(id, method) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft || draft.paymentPlan !== "Monthly") return;
    const now = new Date().toISOString();
    const methodLabel = method === "tfc" ? "Tax-Free Childcare" : method === "voucher" ? "Childcare voucher" : "Card";
    const nextDrafts = drafts.map((item) => item.id === id ? {
      ...item,
      paymentMethod: method,
      paymentPlanStatus: `${methodLabel} route selected`,
      paymentSchedule: (item.paymentSchedule || []).map((installment) => installment.status === "Paid" ? installment : {
        ...installment,
        routeStatus: method === "card" ? "Awaiting PonchoPay card mandate" : method === "tfc" ? "Awaiting TFC auto reconciliation" : "Awaiting voucher auto reconciliation",
      }),
      paymentTimeline: [
        ...(item.paymentTimeline || []),
        { label: `Payment plan route changed to ${methodLabel}`, at: now },
      ],
      updatedAt: now,
    } : item);
    persistDrafts(nextDrafts);
    setStatus(`Payment plan route changed to ${methodLabel} locally.`);
  }

  function payFamilyOutstanding(method = "card") {
    const payableIds = new Set(familyOutstandingInvoices.map((row) => row.id));
    const targets = familyDrafts.filter((draft) => payableIds.has(draft.id));
    if (!targets.length) {
      setStatus("No outstanding family invoices to pay.");
      return;
    }
    const now = new Date().toISOString();
    const ids = new Set(targets.map((draft) => draft.id));
    const autoReconcile = ["tfc", "voucher"].includes(method);
    const methodLabel = method === "tfc" ? "Tax-Free Childcare" : method === "voucher" ? "Childcare voucher" : "Card";
    const referencePrefix = method === "tfc" ? "TFC" : method === "voucher" ? "VOUCHER" : "PORTAL";
    const nextDrafts = drafts.map((draft) => ids.has(draft.id) ? {
      ...draft,
      status: autoReconcile ? "Payment reference pending" : "Prototype paid",
      paymentMethod: method,
      paymentLabel: methodLabel,
      paymentStatus: autoReconcile ? "Awaiting auto reconciliation" : "Paid",
      invoiceStatus: autoReconcile ? "Outstanding until PonchoPay matches the payment" : "Paid receipt issued",
      paymentPlanStatus: draft.paymentPlan === "Monthly" ? (autoReconcile ? `${methodLabel} auto reconciliation pending` : "Plan settled") : draft.paymentPlanStatus,
      paymentSchedule: Array.isArray(draft.paymentSchedule)
        ? draft.paymentSchedule.map((installment) => ({
          ...installment,
          status: autoReconcile ? installment.status : "Paid",
          routeStatus: autoReconcile ? `Awaiting ${methodLabel} auto reconciliation` : "Reconciled by PonchoPay",
          paidAt: autoReconcile ? installment.paidAt : installment.paidAt || now,
        }))
        : draft.paymentSchedule,
      paymentReference: draft.paymentReference || `${referencePrefix}-${Date.now().toString().slice(-6)}`,
      reconciledAt: autoReconcile ? draft.reconciledAt : now,
      paymentTimeline: [
        ...(draft.paymentTimeline || []),
        { label: autoReconcile ? `${methodLabel} bulk reference saved for PonchoPay auto reconciliation` : `${methodLabel} bulk checkout marked received`, at: now },
      ],
      updatedAt: now,
    } : draft);
    persistDrafts(nextDrafts);
    const messages = targets.map((draft, index) => ({
      id: `parent-bulk-receipt-${Date.now()}-${index}`,
      createdAt: now,
      template: autoReconcile ? "Payment reference" : "Payment receipt",
      channel: notificationChannelForEmail(draft.parentEmail || activeFamily.email, "invoices", "Email"),
      recipient: draft.parentEmail || activeFamily.email || "parent@example.com",
      bookingId: draft.id,
      subject: `${autoReconcile ? "Payment reference saved" : "Invoice paid"} · ${draft.activity}`,
      body: autoReconcile
        ? `Hi ${draft.parentName || activeFamily.parentName || "there"}, your ${methodLabel} reference has been saved for ${draft.activity}. Amount awaiting PonchoPay auto reconciliation: ${money(Number(draft.outstandingBalance || draft.total || 0))}.`
        : `Hi ${draft.parentName || activeFamily.parentName || "there"}, your invoice for ${draft.activity} has been marked paid. Amount: ${money(Number(draft.total || 0))}. Method: ${methodLabel}.`,
    }));
    persistMessages([...messages, ...messageLog].slice(0, 70));
    setStatus(autoReconcile ? `${targets.length} ${methodLabel} reference${targets.length === 1 ? "" : "s"} saved for auto reconciliation.` : `${targets.length} outstanding invoice${targets.length === 1 ? "" : "s"} marked paid locally.`);
  }

  async function confirmParentPaymentCheckout() {
    if (!parentPaymentCheckout || !parentCheckoutRows.length) {
      setParentPaymentCheckout(null);
      return;
    }
    const method = parentCheckoutMethod;
    const confirmedTotal = parentCheckoutTotal;
    let checkoutResult = null;
    if (parentCheckoutRows.length === 1 && confirmedTotal > 0) {
      try {
        checkoutResult = await createCheckoutSessionForBooking(parentCheckoutRows[0].draft, {
          amount: confirmedTotal,
          reason: parentCheckoutIsAmendment ? "amendment_balance" : parentCheckoutMode === "next" ? "monthly_instalment" : "invoice_payment",
          idempotencyKey: `apres:${parentCheckoutRows[0].id}:${parentCheckoutReason}:${confirmedTotal.toFixed(2)}`,
        });
      } catch (error) {
        checkoutResult = {
          mode: "error",
          status: "provider_error",
          checkoutUrl: null,
          message: error instanceof Error ? error.message : "PonchoPay checkout could not be created.",
        };
      }
    }
    if (parentPaymentCheckout.mode === "next") {
      parentCheckoutRows.forEach((row) => payNextPlanInstallment(row.id, method));
    } else if (parentPaymentCheckout.mode === "bulk") {
      payFamilyOutstanding(method);
    } else if (method === "card" && checkoutResult?.checkoutUrl && parentCheckoutRows.length === 1) {
      attachPonchoCheckoutToBooking(
        parentCheckoutRows[0].id,
        checkoutResult,
        confirmedTotal,
        parentCheckoutIsAmendment ? "amendment" : "invoice",
      );
      setStatus("PonchoPay checkout link is ready. Open it to complete payment.");
    } else {
      parentCheckoutRows.forEach((row) => payParentBooking(row.id, method, {
        amountOverride: parentPaymentCheckout.amountOverride,
        reason: parentCheckoutIsAmendment ? "amendment" : "invoice",
        checkout: checkoutResult,
      }));
    }
    setParentPaymentCheckout((current) => current ? {
      ...current,
      confirmed: true,
      confirmedTotal,
      confirmedAt: new Date().toISOString(),
      checkout: checkoutResult,
    } : null);
  }

  function sendParentInvoice(id) {
    const draft = drafts.find((item) => item.id === id);
    if (!draft) return;
    const now = new Date().toISOString();
    const isPaid = draft.status === "Prototype paid";
    const methodLabel = draft.paymentMethod === "tfc" || draft.paymentMethod === "tax-free"
      ? "Tax-Free Childcare"
      : draft.paymentMethod === "voucher"
        ? "Childcare voucher"
        : draft.paymentMethod === "invoice"
          ? "Invoice"
          : "Card";
    const message = {
      id: `parent-invoice-${Date.now()}`,
      createdAt: now,
      template: isPaid ? "Payment receipt" : "Payment reminder",
      channel: notificationChannelForEmail(draft.parentEmail || activeFamily.email, "invoices", "Email"),
      recipient: draft.parentEmail || activeFamily.email || "parent@example.com",
      bookingId: draft.id,
      subject: isPaid ? `Receipt ready · ${draft.activity}` : `Invoice ready · ${draft.activity}`,
      body: isPaid
        ? `Hi ${draft.parentName || activeFamily.parentName || "there"}, your receipt for ${draft.activity} is ready in the parent portal. Sessions: ${bookingBlockSummary(draft, 3)}. Amount paid: ${money(Number(draft.total || 0))}. Method: ${methodLabel}. Reference: ${draft.paymentReference || "portal"}.`
        : `Hi ${draft.parentName || activeFamily.parentName || "there"}, your invoice for ${draft.activity} is ready in the parent portal. Sessions: ${bookingBlockSummary(draft, 3)}. Amount due: ${money(Number(draft.total || 0))}. Payment route: ${methodLabel}. ${draft.paymentMethod === "voucher" || draft.paymentMethod === "tfc" || draft.paymentMethod === "tax-free" ? "Add the payment reference so PonchoPay can reconcile it automatically." : "You can pay from the invoice screen."}`,
      status: "Sent",
    };
    persistMessages([message, ...messageLog].slice(0, 70));
    setStatus(isPaid ? "Receipt message added to the parent inbox." : "Invoice message added to the parent inbox.");
  }

  function downloadReceipt(draft) {
    const documentType = draft.status === "Waitlist" ? "request summary" : draft.paymentMethod === "card" ? "receipt" : "invoice summary";
    const receipt = [
      isLaunchMode ? `Après School ${documentType}` : "Après School prototype receipt",
      `${documentType.replace(/^./, (letter) => letter.toUpperCase())}: ${draft.id}`,
      `Parent: ${draft.parentName || activeFamily.parentName}`,
      `Email: ${draft.parentEmail || activeFamily.email}`,
      `Activity: ${draft.activity}`,
      `Site: ${draft.site}`,
      `Dates: ${(draft.days || []).join(", ")}`,
      "Session blocks:",
      ...bookingBlockReceiptLines(draft),
      `Children: ${(draft.children || [draft.childName]).join(", ")}`,
      `Payment method: ${draft.paymentLabel || draft.paymentMethod || "card"}`,
      `Payment route: ${draft.paymentRoute || "PonchoPay"}`,
      `Payment status: ${draft.paymentStatus || draft.paymentPlanStatus || draft.status}`,
      `Invoice status: ${draft.invoiceStatus || "Ready in parent portal"}`,
      `Due today: ${money(Number(draft.dueToday ?? draft.total ?? 0))}`,
      `Outstanding balance: ${money(Number(draft.outstandingBalance || 0))}`,
      `Status: ${draft.status}`,
      `Total: ${money(Number(draft.total || 0))}`,
      "",
      isLaunchMode ? "This document matches the parent portal booking summary." : "Prototype only. No live payment has been processed unless connected to a real payment provider.",
    ].join("\n");
    downloadTextFile(`apres-receipt-${draft.id}.txt`, receipt);
  }

  function createActivity(event) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const days = String(form.get("days") || "")
      .split(",")
      .map((day) => day.trim())
      .filter(Boolean);
    const activity = {
      id: `custom-${Date.now()}`,
      site: form.get("site") || "New site",
      area: form.get("area") || "Local",
      type: form.get("type") || "Wraparound",
      title: form.get("title") || "New activity",
      time: form.get("time") || "15:00-18:00",
      price: Number(form.get("price") || 0),
      age: form.get("age") || "Eligible children",
      capacity: Number(form.get("capacity") || 12),
      days: days.length ? days : ["Mon 8 Jun", "Tue 9 Jun", "Wed 10 Jun", "Thu 11 Jun", "Fri 12 Jun"],
      features: String(form.get("features") || "Draft activity")
        .split(",")
        .map((feature) => feature.trim())
        .filter(Boolean),
      custom: true,
    };
    const next = [activity, ...customSessions].slice(0, 12);
    setCustomSessions(next);
    localStorage.setItem("apres-booking-lab-activities", JSON.stringify(next));
    setActiveId(activity.id);
    setStatus("Prototype activity created and added to the parent booking flow.");
    event.currentTarget.reset();
  }

  function createLaunchPlan(event) {
    event.preventDefault();
    const form = new FormData(event.currentTarget);
    const manualDays = String(form.get("days") || "")
      .split(",")
      .map((day) => day.trim())
      .filter(Boolean);
    const generatedDays = generateSessionDays(
      form.get("startDate"),
      form.get("endDate"),
      Array.from(form.getAll("weekdays")),
    );
    const days = manualDays.length ? manualDays : generatedDays;
    if (!days.length) {
      setStatus("Choose future dates or enter manual dates before creating the launch plan.");
      return;
    }
    const plan = {
      id: `launch-${Date.now()}`,
      createdAt: new Date().toISOString(),
      site: form.get("site") || "New site",
      area: form.get("area") || "",
      schoolContact: form.get("schoolContact") || "",
      activity: form.get("activity") || "After-school care",
      type: form.get("type") || "Wraparound",
      time: form.get("time") || "15:00-18:00",
      price: Number(form.get("price") || 0),
      capacity: Number(form.get("capacity") || 16),
      ratio: form.get("ratio") || "1:8",
      eligibility: form.get("eligibility") || "",
      cancellationHours: Number(form.get("cancellationHours") || rules.cancellationHours),
      amendmentHours: Number(form.get("amendmentHours") || rules.amendmentHours),
      paymentRoute: form.get("paymentRoute") || "PonchoPay card + vouchers",
      paymentMethods: Array.from(form.getAll("paymentMethods")),
      days,
      checklist: {
        safeguarding: Boolean(form.get("safeguarding")),
        registers: Boolean(form.get("registers")),
        payment: Boolean(form.get("payment")),
        comms: Boolean(form.get("comms")),
      },
      status: "Draft launch",
    };
    const activity = {
      id: `custom-${Date.now()}`,
      site: plan.site,
      area: plan.area,
      type: plan.type,
      title: plan.activity,
      time: plan.time,
      price: plan.price,
      age: plan.eligibility || (plan.type === "Wraparound" ? `${plan.site} pupils` : "Open to eligible children"),
      capacity: plan.capacity,
      days: plan.days,
      paymentRoute: plan.paymentRoute,
      cancellationHours: plan.cancellationHours,
      amendmentHours: plan.amendmentHours,
      features: [`Ratio ${plan.ratio}`, plan.paymentRoute, `${plan.paymentMethods.length || 1} payment routes`, "Launch wizard"],
      custom: true,
    };
    const nextPlans = [plan, ...launchPlans].slice(0, 12);
    const nextSessions = [activity, ...customSessions].slice(0, 12);
    setLaunchPlans(nextPlans);
    setCustomSessions(nextSessions);
    localStorage.setItem("apres-booking-lab-launch-plans", JSON.stringify(nextPlans));
    localStorage.setItem("apres-booking-lab-activities", JSON.stringify(nextSessions));
    setActiveId(activity.id);
    setSetupSessionId(activity.id);
    setCapacitySessionId(activity.id);
    setStatus("Launch plan created and activity added to the booking catalogue.");
    event.currentTarget.reset();
  }

