                    {setupRouteRows.map((row) => (
                      <article key={row.route}>
                        <span>{row.route}</span>
                        <strong>{row.count}</strong>
                        <small>open date{row.count === 1 ? "" : "s"}</small>
                      </article>
                    ))}
                    {!setupRouteRows.length && <article><span>Closed</span><strong>0</strong><small>No open dates</small></article>}
