                  <label>Set route<select value={bulkSetupPatch.route} onChange={(event) => setBulkSetupPatch((current) => ({ ...current, route: event.target.value }))}><option>PonchoPay card + vouchers</option><option>PonchoPay vouchers first</option><option>PonchoPay card only</option><option>Invoice / school funded</option></select></label>
